// #145887 (6a993d7ada81dff9be145887) «פיתוח: מסלול קבלת הזמנה והצטרפות לחשבון העסק» — AC2/AC4: ссылка, по которой уже вступили,
// показывает отдельный экран «כבר נעשה שימוש בהזמנה» без формы. Кейс BIZ-INV-014 · spec: specs/business-lifecycle.md (раздел 11).
// Настоящее вступление создаёт аккаунт (в автотестах нельзя) → ответ get_invitation_by_token подменяется на status «accepted»
// для вымышленного токена. Настоящий путь (вступить и открыть ссылку снова) — вручную, кейс BIZ-INV-015.
// Только гость, данных не создаёт, запросов на запись нет → @prod-safe.
import { test, expect } from '../../fixtures';

const HASH = '#145887 #6a993d7ada81dff9be145887';

test.describe(`Приглашение — использованная ссылка (${HASH})`, () => {
  test(`гость: ссылка со статусом «accepted» (подмена ответа) — «כבר נעשה שימוש בהזמנה», путь «איך מקבלים הזמנה חדשה?» и «כניסה לחשבון», формы нет @desktop @prod-safe ${HASH}`, async ({
    page,
  }) => {
    let acceptCalls = 0;
    await page.route('**/functions/v1/accept-invitation**', (route) => {
      acceptCalls += 1;
      return route.abort();
    });
    await page.route('**/rest/v1/rpc/get_invitation_by_token**', (route) =>
      route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ status: 'accepted' }) }),
    );

    await page.goto(`/invite/QA-AUTO-145887-used-${Date.now()}`);

    await expect(page.getByRole('heading', { level: 1, name: 'כבר נעשה שימוש בהזמנה' })).toBeVisible();
    await expect(page.getByTestId('invite-unavailable')).toHaveAttribute('data-reason', 'used');
    await expect(page.getByText('הקישור הזה כבר שימש להצטרפות לחשבון, ואפשר להשתמש בו פעם אחת בלבד.', { exact: false })).toBeVisible();
    await expect(page.getByText('איך מקבלים הזמנה חדשה?')).toBeVisible();
    const login = page.getByRole('link', { name: 'כניסה לחשבון' });
    await expect(login).toBeVisible();
    await expect(login).toHaveAttribute('href', /\/login$/);

    // Формы вступления нет.
    await expect(page.getByTestId('join-steps')).toHaveCount(0);
    await expect(page.getByRole('textbox')).toHaveCount(0);
    await expect(page.getByTestId('join-submit')).toHaveCount(0);
    await expect(page.getByTestId('join-next')).toHaveCount(0);
    expect(acceptCalls).toBe(0);
  });
});
